using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Operations.Domain;
public sealed class BackupEvidence:ITenantEntity{private BackupEvidence(){} public BackupEvidence(Guid municipalityId,string provider,string backupType,DateTimeOffset startedAt){Id=Guid.NewGuid();MunicipalityId=municipalityId;Provider=provider.Trim();BackupType=backupType.Trim();StartedAt=startedAt;Status="STARTED";}public Guid Id{get;private set;}public Guid MunicipalityId{get;private set;}public string Provider{get;private set;}=string.Empty;public string BackupType{get;private set;}=string.Empty;public DateTimeOffset StartedAt{get;private set;}public DateTimeOffset? CompletedAt{get;private set;}public string Status{get;private set;}=string.Empty;public string? Reference{get;private set;}public long? SizeBytes{get;private set;}public DateTimeOffset? RestoreTestedAt{get;private set;}public string? Error{get;private set;}public void Complete(string reference,long? sizeBytes,DateTimeOffset completedAt){Reference=reference;SizeBytes=sizeBytes;CompletedAt=completedAt;Status="COMPLETED";Error=null;}public void Fail(string error,DateTimeOffset completedAt){Error=error;CompletedAt=completedAt;Status="FAILED";}public void MarkRestoreTested(DateTimeOffset at)=>RestoreTestedAt=at;}
